INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f0f72bf0e1188f1593d2','Amedex Pharma Onco Immuno 2025.pdf','91','Oncology/Immunology','A 16-year-old girl, who is a known case of epilepsy
for 5 years, has been started on sodium valproate
and lamotrigine 4 weeks ago after her previous
medications failed to control her seizures. She also
has the history of recurrent urinary tract infections
(UTI) with last episode 6 weeks ago for which she
received amoxicillin. Today, she has presented
with a maculopapular rash and a fever of 38°C.
Which one of the following is the most likely cause
of her presentation?','{"A":"Adverse drug reaction to sodium\nvalproate.","B":"Adverse drug reaction to lamotrigine.","C":"Adverse drug reaction to amoxicillin.","D":"Septicemia.","E":"Drug interaction between lamotrigine\n\nand sodium valproate."}',NULL,NULL,'{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex Pharma Onco Immuno 2025.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-9a071dcee62d","duplicate_sources":[{"record_id":"f0f72bf0e1188f1593d2","record_type":"text_mcq","source_file":"Amedex Pharma Onco Immuno 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex Pharma Onco Immuno 2025.pdf","source_page":91,"source_qid":null},{"record_id":"8d89da2c13a4ee760e92","record_type":"text_mcq","source_file":"Amedex Pharma Onco Immuno 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex Pharma Onco Immuno 2025.pdf","source_page":90,"source_qid":null},{"record_id":"eef83d0f304aecfac15e","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1410,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"f0f72bf0e1188f1593d2","source_file":"Amedex Pharma Onco Immuno 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex Pharma Onco Immuno 2025.pdf","source_year":2025,"source_page":91,"source_qid":null,"domain_hint":"Oncology/Immunology","stem":"A 16-year-old girl, who is a known case of epilepsy\nfor 5 years, has been started on sodium valproate\nand lamotrigine 4 weeks ago after her previous\nmedications failed to control her seizures. She also\nhas the history of recurrent urinary tract infections\n(UTI) with last episode 6 weeks ago for which she\nreceived amoxicillin. Tod