INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('6e112026c8931d7eeb45','Cardiology amedex 2025.pdf','1','Cardiology','A 50-year-old man ipresents to the Emergency Department with chest pain felt behind the sternum
radiating to his jaw. A 12-lead ECG strip is obtained and is as the following photograph. You give him
aspirin and sublingual nitroglycerine and start him on supplemental oxygen by nasal cannula. A troponin
