INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('008089fac064a6c9d88a','Cardiology amedex 2025.pdf','6','Cardiology','A 28-year-old man has had several episodes of palpitations associated with mild dizziness and
sweating over the past year. These attacks occurr usually after exercise and last between 10 and
20 minutes, and often stop after he immerse his face in cold water. He now presents with an attack
that has been going on for 2 hours. His ECG is shown in the following picture. Which one of the
following medications is most likely to be effective?','{"A":"A. Digoxin.","B":"B. Quinidine.","C":"C. Flecainide.","D":"OD. Verapamil.","E":"E. Propranolol."}','D','The rhythm strip shows paroxysmal supraventricular tachycardia (PSVT) at a rate of almost 180
bpm. The mechanism of PSVTs is either a re-entry circuit or automatous focus involving the atria.
The best initial step in management of PSVTs is performing maneuvers that suppress conductivity
in atrioventricular (AV) node such as Valsalva maneuvers, immersion of the face in cold water, etc.
If non-medical measures failed, preferred medical management is with intravenous adenosine
(preferred) or verapamil as the first-line medications.

(Option A) Digoxin is no more recommended for management of PSVT.

(Options B and C) Quinidine and flecainide are antiarrhythmic drugs, but not used for
management of PSVT.

(Option E) Beta blockers such as metoprolol, propranolol and atenolol are second-line drugs.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[6],"source_qid":null,"duplicate_group_id":"exact-52bf851c0d57","duplicate_sources":[{"record_id":"008089fac064a6c9d88a","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":6,"source_qid":null},{"record_id":"35fd04e0e94867dd4bdb","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":27,"source_qid":null},{"record_id":"09902bb3a61e9e4a0a4b","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":29,"source_qid":null},{"record_id":"bfbfb3ba2cee9f709dd8","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":34,"source_qid":"244"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"008089fac064a6c9d88a","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":6,"supporting_pages":[6],"source_qid":null,"domain_hint":"Cardiology","stem":"A 28-year-old man has had several episodes of palpitations associated with mild dizziness and\nsweating over the past year. These attacks occurr usually after exercise and last between 10 and\n20 minutes, and often stop after he immerse his face in cold water. He now presents with an attack\nthat has been going on for 2 hours. His ECG is shown in the following picture. Which one of the\nfollowing medications is most likely to be effective?","options":{"A":"A. Digoxin.","B":"B. Quinidine.","C":"C. Flecainide.","D":"OD. Verapamil.","E":"E. Propranolol."},"source_answer":"D","source_explanation":"The rhythm strip shows paroxysmal supraventricular tachycardia (PSVT) at a rate of almost 180\nbpm. The mechanism of PSVTs is either a re-entry circuit or automatous focus involving the atria.\nThe best initial step in management of PSVTs is performing maneuvers that suppress conductivity\nin atrioventricular (AV) node such as Valsalva maneuvers, immersion of the face in cold water, etc.\nIf non-medical measures failed, preferred medical management is with intravenous adenosine\n(preferred) or verapamil as the first-line medications.\n\n(Option A) Digoxin is no more recommended for management of PSVT.\n\n(Options B and C) Quinidine and flecainide are antiarrhythmic drugs, but not used for\nmanagement of PSVT.\n\n(Option E) Beta blockers such as metoprolol, propranolol and atenolol are second-line drugs.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","drug","management"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"52bf851c0d57efb2452e046ebae6eb7d9cb8fafb","duplicate_group_id":"exact-52bf851c0d57","duplicate_sources":[{"record_id":"008089fac064a6c9d88a","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":6,"source_qid":null},{"record_id":"35fd04e0e94867dd4bdb","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_p