INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d57e0bbb946f4480d630','Cardiology amedex 2025.pdf','13','Cardiology','A 76-year-old man comes to your clinic for a routine health check-up. His blood pressure is 110/90 mmHg,
and his pulse rate is 92 bpm. He is on no medications except daily multivitamins. As part of the evaluation,
an ECG is obtained, which is shown in the following photograph. Which of the following is the next best
step in management?',NULL,'C','The ECG shows a sinus rhythm with increased PR interval characteristic of first-degree atrioventricular
block. The condition can be caused by:
e Age-related fibrosis and degeneration of AV node — the most common cause
e Drugs: digoxin, beta-blockers, calcium channel blockers
e Increased vagal tone.
First-degree heart block is characterized by PR interval> 200 ms (0.2 s) on ECG, normal QRS complexes
in terms of duration and spacing, and the presence of a P wave before each QRS.
This is quite common among the elderly due to age-related fibrotic changes in the cardiac conductive
system. Asymptomatic patients do not need treatment and must be reassured. With symptoms (e.g.,
dizziness, shortness of breath, chest pain, etc.) atropine or pacemaker (if unresponsive to atropine) is
considered.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[13],"source_qid":null,"duplicate_group_id":"exact-abff44aa2ee9","duplicate_sources":[{"record_id":"d57e0bbb946f4480d630","record_type":"visual_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":13,"source_qid":null},{"record_id":"031070b22d5e199b3578","record_type":"visual_mcq","source_file":"AMEDEX 2025 CVS (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (2).pdf","source_page":1,"source_qid":null}],"parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","parser_mode":"v282_visual_page_asset","text_method":"source_page_image+best_available_text","visual_asset":"visual_assets/Cardiology_amedex_2025__a83b80e8c658/page_00013.jpg","asset_preview_url":"https://drive.google.com/file/d/1HVTMwxYUkZQWB4JlEII08JbDVkjdfhvJ/preview"}','visual_assets/Cardiology_amedex_2025__a83b80e8c658/page_00013.jpg','https://drive.google.com/thumbnail?id=1HVTMwxYUkZQWB4JlEII08JbDVkjdfhvJ&sz=w1600','source_page_image',NULL,'needs_verification','[]','medium','{"record_id":"d57e0bbb946f4480d630","record_type":"visual_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":13,"supporting_pages":[13],"source_qid":null,"domain_hint":"Cardiology","stem":"A 76-year-old man comes to your clinic for a routine health check-up. His blood pressure is 110/90 mmHg,\nand his pulse rate is 92 bpm. He is on no medications except daily multivitamins. As part of the evaluation,\nan ECG is obtained, which is shown in the following photograph. Which of the following is the next best\nstep in management?","options":null,"options_mode":"source_page_image","visual_asset":"visual_assets/Cardiology_amedex_2025__a83b80e8c658/page_00013.jpg","source_answer":"C",