INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('23361b4d33350decda37','Cardiology amedex 2025.pdf','14','Cardiology','A 55-year-old man presents with concerns about developing abdominal aortic aneurysm
(AAA), as his father was diagnosed with the same disease at the age of 57 years. He has
smoked 20 cigarettes a day for the past 15 years. On examination, he has a blood pressure
of 130/75 mmHg. Which one of the following is the best advice to give?','{"A":"A. Reassure as AAA has no genetic predisposition.","B":"OB. Arrange for regular screening with ultrasonography.","C":"C. Order a CT angiogram.","D":"D. Start him on aspirin.","E":"E. Start him on anti-hypertensive medications."}','B','Patients with a first- degree relative with abdominal aortic aneurysm (AAA) have a 20%
increased risk of developing AAA compared to normal population; for this reason, he needs
to be screened for AAA. Screening is performed with ultrasonography as the best
investigation with very high index of sensitivity and specificity.

NOTE - Advancing age is the most common risk factor for AAA. Other risk factors
include male gender, family history, smoking, hypercholesterolemia, diabetes mellitus,
and chronic hypertension.

(Option A) Reassurance is inappropriate because he has increased risk of AAA due to the
family history.

(Option C) CT angiogram is indicated once the surgical repair is planned.
(Option D) Aspirin is used neither for prophylaxis, nor treatment of AAA.

(Option E) Anti-hypertensive medications are of no benefit because the patient is
normotensive.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[14],"source_qid":null,"duplicate_group_id":"exact-18edf9aa36df","duplicate_sources":[{"record_id":"23361b4d33350decda37","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":14,"source_qid":null},{"record_id":"1fd820c387b6c4daabe7","record_type":"visual_mcq","source_file":"AMEDEX 2025 CVS (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (2).pdf","source_page":52,"source_qid":null},{"record_id":"d2e4a82461385e340063","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":44,"source_qid":"255"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"23361b4d33350decda37","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":14,"supporting_pages":[14],"source_qid":null,"domain_hint":"Cardiology","stem":"A 55-year-old man presents with concerns about developing abdominal aortic aneurysm\n(AAA), as his father was diagnosed with the same disease at the age of 57 years. He has\nsmoked 20 cigarettes a day for the past 15 years. On examination, he has a blood pressure\nof 130/75 mmHg. Which one of the following is the best advice to give?","options":{"A":"A. Reassure as AAA has no genetic predisposition.","B":"OB. Arrange for regular screening with ultrasonography.","C":"C. Order a CT angiogram.","D":"D. Start him on aspirin.","E":"E. Start him on anti-hypertensive medications."},"source_answer":"B","source_explanation":"Patients with a first- degree relative with abdominal aortic aneurysm (AAA) have a 20%\nincreased risk of developing AAA compared to normal population; for this reason, he needs\nto be screened for AAA. Screening is performed with ultrasonography as the best\ninvestigation with very high index of sensitivity and specificity.\n\nNOTE - Advancing age is the most common risk factor for AAA. Other risk factors\ninclude male gender, family history, smoking, hypercholesterolemia, diabetes mellitus,\nand chronic hypertension.\n\n(Option A) Reassurance is inappropriate because he has increased risk of AAA due to the\nfamily history.\n\n(Option C) CT angiogram is indicated once the surgical repair is planned.\n(Option D) Aspirin is used neither for prophylaxis, nor treatment of AAA.\n\n(Option E) Anti-hypertensive medications are of no benefit because the patient is\nnormotensive.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","diabetes","hypertension","prophyl","screen","screening","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"18edf9aa36dfa85c8f6716c2cc6dd75308fe0725","duplicate_group_id":"exact-18edf9aa36df","duplicate_sources":[{"record_id":"23361b4d33350decda37","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":14,"source_qid":null},{"record_id":"1fd820c387b6c4daabe7","record_type":"visual_mcq","source_file":"AMEDEX 2025 CVS (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (2).pdf","source_page":52,"source_qid":null},{"record_id":"d2e4a82461385e340063","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":44,"source_qid":"255"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
