INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('4e7f0db8cb53d3fbd9fb','Cardiology amedex 2025.pdf','16','Cardiology','Which one of the following is NOT a contraindication to thrombolytics use in a patient with ST elevation myocardial
infarction?','{"A":"A. Ischemic stroke in the past 3 months.","B":"B. Hemorrhagic stroke in the past 10 years.","C":"OC. Heavy menstrual bleeding.","D":"D. Coagulation disorders.","E":"E. Gastrointestinal bleeding within the past 4 weeks."}','C','Absolute contraindications for fibrinolytic use in STEMI include the following:

e Prior intracranial hemorrhage (ICH)

e¢ Known structural cerebral vascular lesion

¢ Known malignant intracranial neoplasm

e Ischemic stroke within 3 months

e Suspected aortic dissection

e Active bleeding or bleeding diathesis (excluding menses)

¢ Significant closed head trauma or facial trauma within 3 months

e Intracranial or intraspinal surgery within 2 months

e Severe uncontrolled hypertension (unresponsive to emergency therapy)
e For streptokinase, prior treatment within the previous 6 months

Relative contraindications for fibrinolytic use in STEMI include the following:

e History of chronic, severe, poorly controlled hypertension

¢ Significant hypertension on presentation (systolic blood pressure >180 mm Hg or diastolic blood pressure
>110 mm Hg

e Traumatic or prolonged (>10 minutes) cardiopulmonary resuscitation (CPR) or major surgery less than 3
weeks previously

e History of prior ischemic stroke not within the last 3 months

e Dementia

¢ Recent (within 2-4 weeks) internal bleeding

¢ Noncompressible vascular punctures

e Pregnancy

e Active peptic ulcer

e Current use of an anticoagulant (e.g., warfarin) that has produced an elevated international normalized ratio
(INR) higher than 1.7 or a prothrombin time (PT) longer than 15 seconds

Of the given options, only heavy menstrul bleeding is not an absolute contraindication to thrombolytic therapy.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[16],"source_qid":null,"duplicate_group_id":"exact-25368dcc009f","duplicate_sources":[{"record_id":"4e7f0db8cb53d3fbd9fb","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":16,"source_qid":null},{"record_id":"645510ca5916076b48ca","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":14,"source_qid":"224"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"4e7f0db8cb53d3fbd9fb","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":16,"supporting_pages":[16],"source_qid":null,"domain_hint":"Cardiology","stem":"Which one of the following is NOT a contraindication to thrombolytics use in a patient with ST elevation myocardial\ninfarction?","options":{"A":"A. Ischemic stroke in the past 3 months.","B":"B. Hemorrhagic stroke in the past 10 years.","C":"OC. Heavy menstrual bleeding.","D":"D. Coagulation disorders.","E":"E. Gastrointestinal bleeding within the past 4 weeks."},"source_answer":"C","source_explanation":"Absolute contraindications for fibrinolytic use in STEMI include the following:\n\ne Prior intracranial hemorrhage (ICH)\n\ne¢ Known structural cerebral vascular lesion\n\n¢ Known malignant intracranial neoplasm\n\ne Ischemic stroke within 3 months\n\ne Suspected aortic dissection\n\ne Active bleeding or bleeding diathesis (excluding menses)\n\n¢ Significant closed head trauma or facial trauma within 3 months\n\ne Intracranial or intraspinal surgery within 2 months\n\ne Severe uncontrolled hypertension (unresponsive to emergency therapy)\ne For streptokinase, prior treatment within the previous 6 months\n\nRelative contraindications for fibrinolytic use in STEMI include the following:\n\ne History of chronic, severe, poorly controlled hypertension\n\n¢ Significant hypertension on presentation (systolic blood pressure >180 mm Hg or diastolic blood pressure\n>110 mm Hg\n\ne Traumatic or prolonged (>10 minutes) cardiopulmonary resuscitation (CPR) or major surgery less than 3\nweeks previously\n\ne History of prior ischemic stroke not within the last 3 months\n\ne Dementia\n\n¢ Recent (within 2-4 weeks) internal bleeding\n\n¢ Noncompressible vascular punctures\n\ne Pregnancy\n\ne Active peptic ulcer\n\ne Current use of an anticoagulant (e.g., warfarin) that has produced an elevated international normalized ratio\n(INR) higher than 1.7 or a prothrombin time (PT) longer than 15 seconds\n\nOf the given options, only heavy menstrul bleeding is not an absolute contraindication to thrombolytic therapy.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","anticoag","cpr","fibrinol","hypertension","pregnan","resuscitation","therapy","thrombol","treatment","warfarin"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"25368dcc009f02535e2b5820a3400d3671a17b17","duplicate_group_id":"exact-25368dcc009f","duplicate_sources":[{"record_id":"4e7f0db8cb53d3fbd9fb","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":16,"source_qid":null},{"record_id":"645510ca5916076b48ca","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":14,"source_qid":"224"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
