INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f41cf12cd60c47e6d915','Cardiology amedex 2025.pdf','20','Cardiology','A 65-year-old man presents with history of two episodes of abdominal pain after meals. As
a part of workup plan, an abdominal ultrasonography is performed, which showed
gallstones in the gallbladder and a 3.8 cm abdominal aortic aneurysm (AAA). Which one of
the following is the recommended management of this asymptomatic AAA?','{"A":"A. Ultrasonography every 12 months.","B":"B. CT scan every 12 months.","C":"OC. Ultrasonography every 24 months.","D":"D. CT scan every 24 months.","E":"E. CT scan or ultrasonography every 12 months."}','C','Ultrasonography is the preferred method for screening and surveillance of asymptomatic
AAA. The screening intervals depend on the size of the AAA and are according to the
following table:

Given the size of the AAA (3.8 cm), it should be monitored every 24 months with
ultrasonography.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[20],"source_qid":null,"duplicate_group_id":"exact-eba07bcf4b86","duplicate_sources":[{"record_id":"f41cf12cd60c47e6d915","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":20,"source_qid":null},{"record_id":"a253af15e0ee109a6252","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":272,"source_qid":null},{"record_id":"6e3869d7ab54959a2a60","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":45,"source_qid":"256"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"f41cf12cd60c47e6d915","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":20,"supporting_pages":[20],"source_qid":null,"domain_hint":"Cardiology","stem":"A 65-year-old man presents with history of two episodes of abdominal pain after meals. As\na part of workup plan, an abdominal ultrasonography is performed, which showed\ngallstones in the gallbladder and a 3.8 cm abdominal aortic aneurysm (AAA). Which one of\nthe following is the recommended management of this asymptomatic AAA?","options":{"A":"A. Ultrasonography every 12 months.","B":"B. CT scan every 12 months.","C":"OC. Ultrasonography every 24 months.","D":"D. CT scan every 24 months.","E":"E. CT scan or ultrasonography every 12 months."},"source_answer":"C","source_explanation":"Ultrasonography is the preferred m