INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('18df1a84b2623c7b0376','Cardiology amedex 2025.pdf','32','Cardiology','Which one of the following is not indicated in management of pulmonary edema?','{"A":"A. Continuous positive airway pressure (CPAP).","B":"B. Bilevel positive airway pressure (BiPAP).","C":"C. Glyceryl trinitrate.","D":"OD. Oral forusemide.","E":"E. Morphine."}','D','Management of acute pulmonary oedema is as follows:
e Oxygen 10-15 L/min by Hudson mask and reservoir bag.
¢ Once the patient is stable continue oxygen 2-6 L/min by nasal cannula.

¢ Intravenous forusemide - it is one of the most essential steps in treatment of pulmonary
oedema by decreasing the volume overload. If taken orally, forusemide takes time to work
and is not effective in treatment.

¢ Glyceryl trinitrate — it reduces the preload; it is essential to titrate the dose to maintain
systolic blood pressure above 100mmHg.

¢ Morphine — by decreasing the sympathetic tone, it results in vasodilation and reduction of
preload

¢ CPAP and BiPAP — these non-invasive methods of ventilation are used to reduce alveolar
and pulmonary edema by reducing the venous return and preload.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[32],"source_qid":null,"duplicate_group_id":"exact-bdebfa179913","duplicate_sources":[{"record_id":"18df1a84b2623c7b0376","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":32,"source_qid":null},{"record_id":"dca32866f703f4c1e1f6","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (2).pdf","source_page":71,"source_qid":null},{"record_id":"5633af9c964062785369","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (2).pdf","source_page":72,"source_qid":null},{"record_id":"15af3f80f090e945cd4e","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":5,"source_qid":"29"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"18df1a84b2623c7b0376","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":32,"supporting_pages":[32],"source_qid":null,"domain_hint":"Cardiology","stem":"Which one of the following is not indicated in management of pulmonary edema?","options":{"A":"A. Continuous positive airway pressure (CPAP).","B":"B. Bilevel positive airway pressure (BiPAP).","C":"C. Glyceryl trinitrate.","D":"OD. Oral forusemide.","E":"E. Morphine."},"source_answer":"D","source_explanation":"Management of acute pulmonary oedema is as follows:\ne Oxygen 10-15 L/min by Hudson mask and reservoir bag.\n¢ Once the patient is stable continue oxygen 2-6 L/min by nasal cannula.\n\n¢ Intravenous forusemide - it is one of the most essential steps in treatment of pulmonary\noedema by decreasing the volume overload. If taken orally, forusemide takes time to work\nand is not effective in treatment.\n\n¢ Glyceryl trinitrate — it reduces the preload; it is essential to titrate the dose to maintain\nsystolic blood pressure above 100mmHg.\n\n¢ Morphine — by decreasing the sympathetic tone, it results in vasodilation and reduction of\npreload\n\n¢ CPAP and BiPAP — these non-invasive methods of ventilation are used to reduce alveolar\nand pulmonary edema by reducing the venous return and preload.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","dose","management","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"bdebfa179913be4754bbdbfb864fc65432e9e86c","duplicate_group_id":"exact-bdebfa179913","duplicate_sources":[{"record_id":"18df1a84b2623c7b0376","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":32,"source_qid":null},{"record_id":"dca32866f703f4c1e1f6","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (2).pdf","source_page":71,"source_qid":null},{"record_id":"5633af9c964062785369","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (2).pdf","source_page":72,"source_qid":null},{"record_id":"15af3f80f090e945cd4e","record_type":"text_mcq","source_file":"Amedex 2