INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('75bd2db6d2981ad49b14','Cardiology amedex 2025.pdf','39','Cardiology','A 60-year-old man presents with leg pain for the past 6 months. The pain becomes worse with walking and is relieved when he rests. There is no pain at rest. He has smoked 20 cigarettes per day for the past 30 years. On examination, he is obese with a BMI of 31 and has a blood pressure of 160/110 mmHg on two readings 20 minutes apart. Distal pulses of the left lower limb, including the dorsalis pedis, are barely perceptible. The skin of the legs is shiny and hairless. Mild muscular atrophy of the leg is noted. Ankle-brachial index (ABI) is 0.7. Which one of the following would be the most appropriate management and advice?','{"A":"Smoking cessation, exercise and follow-up in three months.","B":"Smoking cessation, statins and ACE inhibitors.","C":"Duplex Doppler venous ultrasonography.","D":"Aspirin, metoprolol, and statins.","E":"Referral for vascular surgery."}','B',NULL,'{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[39],"source_qid":null,"duplicate_group_id":null,"duplicate_sources":[],"parser_version":"manual-review-batch021-2026-09-24","parser_mode":"manual_visual_review_batch021","text_method":"manual_visual_transcription","visual_asset":"manual_review_assets/Cardiology_amedex_2025__a83b80e8c658/page_00039.jpg","asset_preview_url":"https://drive.google.com/file/d/1B_wfCU9Vw8G93gBpdQmN_NqCChe-B44U/preview"}','manual_review_assets/Cardiology_amedex_2025__a83b80e8c658/page_00039.jpg','https://drive.google.com/thumbnail?id=1B_wfCU9Vw8G93gBpdQmN_NqCChe-B44U&sz=w1600','text',NULL,'needs_verification','[]','medium','{"batch":"021","sour