INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('4b5b8bb8520497481b4d','Cardiology amedex 2025.pdf','42','Cardiology','A 73-year-old man presents with swelling of his left leg for the past three hours. Evaluation
establishes the diagnosis of a deep vein thrombosis (DVT) in the left lower leg. A Doppler
ultrasound reveals deep vein thrombosis in the calf as well as popliteal and femoral veins.
His past medical history is negative for previous DVT. Which one of the following is the next
best in management of this patient?','{"A":"A. Angiography.","B":"B. Angioplasty.","C":"OC. Heparin.","D":"D. Warfarin.","E":"E. Aspirin."}','C','All patients with DVT are initially managed by injectable heparin (either intravenous
unfractionated or subcutaneous low molecular weight heparin). Warfarin can be started
within 24-48 hours with close monitoring of INR. Once INR is in the therapeutic range of 2-
3, heparin can be withheld. Warfarin should be continued for 6 months at least. Patients
should see their GP on a regular basis for close monitoring of the INR.

(Option A) DVT is the presence of clot in the deep veins. Arteriography evaluates arterial
structure and thromboses within arteries.

(Option B) Angioplasty is performed for revascularizaion in arterial problmes with no role in
DVT.

(Option D) Warfarin is indicated in this patient after initial anticoagulation with heparin.

(Option E) Antiplatelet therapy with aspirin or clopidogrel does not provide adequate
anticoagulation for prevention of DVT.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[42],"source_qid":null,"duplicate_group_id":"exact-a3bb9084887c","duplicate_sources":[{"record_id":"4b5b8bb8520497481b4d","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":42,"source_qid":null},{"record_id":"50bf584859ddecdb756f","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":17,"source_qid":null},{"record_id":"0bfc53937b0aca252b3c","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":66,"source_qid":"275"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"4b5b8bb8520497481b4d","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":42,"supporting_pages":[42],"source_qid":null,"domain_hint":"Cardiology","stem":"A 73-year-old man presents with swelling of his left leg for the past three hours. Evaluation\nestablishes the diagnosis of a deep vein thrombosis (DVT) in the left lower leg. A Doppler\nultrasound reveals deep vein thrombosis in the calf as well as popliteal and femoral veins.\nHis past medical history is negative for previous DVT. Which one of the following is the next\nbest in management of this patient?","options":{"A":"A. Angiography.","B":"B. Angioplasty.","C":"OC. Heparin.","D":"D. Warfarin.","E":"E. Aspirin."},"source_answer":"C","source_explanation":"All patients with DVT are initially managed by injectable heparin (either intravenous\nunfractionated or subcutaneous low molecular weight heparin). Warfarin can be started\nwithin 24-48 hours with close monitoring of INR. Once INR is in the therapeutic range of 2-\n3, heparin can be withheld. Warfarin should be continued for 6 months at least. Patients\nshould see their GP on a regular basis for close monitoring of the INR.\n\n(Option A) DVT is the presence of clot in the deep veins. Arteriography evaluates arterial\nstructure and thromboses within arteries.\n\n(Option B) Angioplasty is performed for revascularizaion in arterial problmes with no role in\nDVT.\n\n(Option D) Warfarin is indicated in this patient after initial anticoagulation with heparin.\n\n(Option E) Antiplatelet therapy with aspirin or clopidogrel does not provide adequate\nanticoagulation for prevention of DVT.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","anticoag","antiplatelet","management","therapy","warfarin"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"a3bb9084887c87df2b64981aeec0c5484caf5cbc","duplicate_group_id":"exact-a3bb9084887c","duplicate_sources":[{"record_id":"4b5b8bb8520497481b4d","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":42,"source_qid":null},{"record_id":"50bf584859ddecdb756f","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":17,"source_qid":null},{"record_id":"0bfc53937b0aca252b3c","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handb