INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('02b616ddf235424e3000','Cardiology amedex 2025.pdf','46','Cardiology','A 62-year-old woman is seen in the ward 24 hours after a non-ST segment elevation
myocardial infarction (NSTEMI). She complains of light-headedness. The radial pulse
is difficult to feel, blood pressure is 90/60 mmHg, heart sounds are muffled, and there
is evidence of biventricular cardiac failure. Which one of the following rhythm strips
would be of most concern in this situation?',NULL,'A','The clinical picture of weak pulses, tachycardia and lightheadedness are suggestive
of a tachyarrhythmia of ventricular origin, i.e. ventricular tachycardia (VT) or
ventricular fibrillation (VF). The latter is always associated with loss of consciousness;
therefore, cannot be considered in this woman.
The only rhythm strip consistent with the clinical picture is option A, which shows VT.
VT is the most common arrhythmia occuring after myocardial infarction (MI). They are
in particular common in the first 24 hours post-MI.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[46],"source_qid":null,"duplicate_group_id":"exact-69593cf66e96","duplicate_sources":[{"record_id":"02b616ddf235424e3000","record_type":"visual_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":46,"source_qid":null}],"parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","parser_mode":"v282_visual_page_asset","text_method":"source_page_image+best_available_text","visual_asset":"visual_assets/Cardiology_amedex_2025__a83b80e8c658/page_00046.jpg","asset_preview_url":"https://drive.google.com/file/d/17ahdzhwdS133F-PqyAbW8pYoO4hN3qhA/preview"}','visual_assets/Cardiology_amedex_2025__a83b80e8c658/page_00046.jpg','https://drive.google.com/thumbnail?id=17ahdzhwdS133F-PqyAbW8pYoO4hN3qhA&sz=w1600','source_page_image',NULL,'needs_verification','[]','low','{"record_id":"02b616ddf235424e3000","record_type":"visual_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":46,"supporting_pages":[46],"source_qid":null,"domain_hint":"Cardiology","stem":"A 62-year-old woman is seen in the ward 24 hours after a non-ST segment elevation\nmyocardial infarction (NSTEMI). She complains of light-headedness. The radial pulse\nis difficult to feel, blood pressure is 90/60 mmHg, heart sounds are muffled, and there\nis evidence of biventricular cardiac failure. Which one of the following rhythm strips\nwould be of most concern in this situation?","options":null,"options_mode":"source_page_image","visual_asset":"visual_assets/Cardiology_amedex_2025__a83b80e8c658/page_00046.jpg","source_answer":"A","source_explanation":"The clinical picture of weak pulses, tachycardia and lightheadedness are suggestive\nof a tachyarr