INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('5fb6416fef3de5b3cd74','Cardiology amedex 2025.pdf','54','Cardiology','A 70-year-old man, farmer by profession, presents to the Emergency Department after he experienced
chest pain of 20 minutes duration following physical activity. When the pain started, he took 3 puffs of
glyceryl trinitrate but there was no relief. In the Emergency Department though, the pain alleviated with
oxygen. On further questioning, you realize that he is on aspirin, metoprolol and sublingual glycery!
trinitrate spray on an ''as needed'' basis. During the past 6 months, he has had only 3 episodes of chest
pain subsided just by rest. He saw his GP 6 months ago when he received his last prescription. Which one
of the following is the most likely explanation of failure of glyceryl trinitrate to relieve his symptoms?','{"A":"A. Onset of unstable angina.","B":"B. Nitrate tolerance.","C":"OC. Reduced drug potency.","D":"D. Poor absorption through the mouth.","E":"E. Onset of myocardial infarction."}','C','The given scenario is more likely due to expiration of the glyceryl trinitrate. It is important to remember to
remind the patients to update their GTN sprays or pearls. Expired GTN has reduced potency and effect on
relieving the ischemic pain.

The given scenario is more likely to have occurred due to expiration of the glyceryl trinitrate. It is important
to remind the patients to update their GTN sprays or pearls. Expired GTN has reduced potency and effect
on relieving the ischemic pain. Since this patient has refilled his prescription 6 months ago, it is likely that
the drug is past its expiry date and lost the desired potency.

Nitrate tolerance (option B) is a possibility and concern in patients who take GTN or other nitrates on a
regular basis. After some time, resistance to nitrates develops and the ability of pain control diminishes. In
this patient, however, tolerance is very unlikely, as he is not been a regular user of nitrates and has used
them occasionally on an ‘as-needed’ basis.

In patients with unstable angina or myocardial infarction, the pain may not respond to nitrates. However,
this patient is not likely to have these because it is unlikely for unstable angina (option A) or myocardial
infarction (option E) to respond to oxygen but not to nitrates.

(Option D) GTN adequately and effectively absorbs through the mouth.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[54],"source_qid":null,"duplicate_group_id":"exact-85dab405d447","duplicate_sources":[{"record_id":"5fb6416fef3de5b3cd74","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":54,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"5fb6416fef3de5b3cd74","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":54,"supporting_pages":[54],"source_qid":null,"domain_hint":"Cardiology","stem":"A 70-year-old man, farmer by profession, presents to the Emergency Department after he experienced\nchest pain of 20 minutes duration following physical activity. When the pain started, he took 3 puffs of\nglyceryl trinitrate but there was no relief. In the Emergency Department though, the pain alleviated with\noxygen. On further questioning, you realize that he is on aspirin, metoprolol and sublingual glycery!\ntrinitrate spray on an ''as needed'' basis. During the past 6 months, he has had only 3 episodes of chest\npain subsided just by rest. He saw his GP 6 months ago when he received his last prescription. Which one\nof the following is the most likely explanation of failure of glyceryl trinitrate to relieve his symptoms?","options":{"A":"A. Onset of unstable angina.","B":"B. Nitrate tolerance.","C":"OC. Reduced drug potency.","D":"D. Poor absorption through the mouth.","E":"E. Onset of myocardial infarction."},"source_answer":"C","source_explanation":"The given scenario is more likely due to expiration of the glyceryl trinitrate. It is important to remember to\nremind the patients to update their GTN sprays or pearls. Expired GTN has reduced potency and effect on\nrelieving the ischemic pain.\n\nThe given scenario is more likely to have occurred due to expiration of the glyceryl trinitrate. It is important\nto remind the patients to update their GTN sprays or pearls. Expired GTN has reduced potency and effect\non relieving the ischemic pain. Since this patient has refilled his prescription 6 months ago, it is likely that\nthe drug is past its expiry date and lost the desired potency.\n\nNitrate tolerance (option B) is a possibility and concern in patients who take GTN or other nitrates on a\nregular basis. After some time, resistance to nitrates develops and the ability of pain control diminishes. In\nthis patient, however, tolerance is very unlikely, as he is not been a regular user of nitrates and has used\nthem occasionally on an ‘as-needed’ basis.\n\nIn patients with unstable angina or myocardial infarction, the pain may not respond to nitrates. However,\nthis patient is not likely to have these because it is unlikely for unstable angina (option A) or myocardial\ninfarction (option E) to respond to oxygen but not to nitrates.\n\n(Option D) GTN adequately and effectively absorbs through the mouth.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["drug","duration"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"85dab405d447639596334241d571e21825afc253","duplicate_group_id":"exact-85dab405d447","duplicate_sources":[{"record_id":"5fb6416fef3de5b3cd74","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":54,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
