INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('3dfc90177b1f3c58ad06','Cardiology amedex 2025.pdf','56','Cardiology','A 65-year-old man presents to the emergency department with complaints of palpitation for the past 3
days which is worse today. He is on thyroxin 50 mcg for hypothyroidism. On examination, he has a blood
pressure of 140/90 mmHg and an irregular pulse. An ECG is obtained and is as shown in the picture.
Which one of the following would be the next step in management?','{"A":"\\ a J —4 ma Tt itt Tit Win ttt ttt tt i | , ‘ | :\nsHEEERITEEEEeeeiinineeeei eu ttnartenn ane\nSHH","B":"Stop thyroxin.\n¥ OB. Start him on metoprolol.","C":"Arrange for measuring plasma TSH level.","D":"Give him intravenous atropine.","E":"Place a percutaneous pacemaker."}','B','The clinical findings of palpitation and irregular pulse in conjunction with ECG establish the diagnosis of
atrial fibrillation (AF). AF may be idiopathic or due to a variety of conditions, with chronic hypertension
being the most common cause. Hyperthyroidism is another etiology for AF. For every patient with AF, TSH
should be measured (option C) and an echocardiography performed, but these steps are considered
once the patient is started on appropriate treatment. For patients with symptomatic AF, treatment either
with rate control (preferred) with metoprolol or calcium channel blockers or rhythm control should be
started immediately.
Considering anticoagulation for prevention of thromboembolic events is another important step for AF with
more than 48-hour duration or of unknown duration. Investigation for reversible causes of AF is considered
once the patient is given appropriate initial management.
A TSH level below the normal lower limit is associated with an increased risk of AF, as is hyperthyroid
state associated with excess doses of thyroxin. Even in the presence of increased levels of T4 in the
plasma due to excess thyroxin, stopping the thyroxin (option A) will not lead to rapid improvement of
symptoms.
Atropine (option D) and pacemakers (option E) are used for treatment of symptomatic bradycardia, which
is not the case here.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-624071963e77","duplicate_sources":[{"record_id":"3dfc90177b1f3c58ad06","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":56,"source_qid":null},{"record_id":"251531e5319a1b2bc9b7","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":168,"source_qid":null},{"record_id":"33c584f7a77e843c4e74","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":37,"source_qid":"246"}],"parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','high','{"record_id":"3dfc90177b1f3c58ad06","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":56,"source_qid":null,"domain_hint":"Cardiology","stem":"A 65-year-old man presents to the emergency department with complaints of palpitation for the past 3\ndays which is worse today. He is on thyroxin 50 mcg for hypothyroidism. On examination, he has a blood\npressure of 140/90 mmHg and an irregular pulse. An ECG is obtained and is as shown in the picture.\nWhich one of the following would be the next step in management?","options":{"A":"\\ a J —4 ma Tt itt Tit Win ttt ttt tt i | , ‘ | :\nsHEEERITEEEEeeeiinineeeei eu ttnartenn ane\nSHH","B":"Stop thyroxin.\n¥ OB. Start him on metoprolol.","C":"Arrange for measuring plasma TSH level.","D":"Give him intravenous atropine.","E":"Place a percutaneous pacemaker."},"source_answer":"B","source_explanation":"The clinical findings of palpitation and irregular pulse in conjunction with ECG establish the diagnosis of\natrial fibrillation (AF). AF may be idiopathic or due to a variety of conditions, with chronic hypertension\nbeing the most common cause. Hyperthyroidism is another etiology for AF. For every patient with AF, TSH\nshould be measured (option C) and an echocardiography performed, but these steps are considered\nonce the patient is started on appropriate treatment. For patients with symptomatic AF, treatment either\nwith rate control (preferred) with metoprolol or calcium channel blockers or rhythm control should be\nstarted immediately.\nConsidering anticoagulation for prevention of thromboembolic events is another important step for AF with\nmore than 48-hour duration or of unknown duration. Investigation for reversible causes of AF is considered\nonce the patient is given appropriate initial management.\nA TSH level below the normal lower limit is associated with an increased risk of AF, as is hyperthyroid\nstate associated with excess doses of thyroxin. Even in the presence of increased levels of T4 in the\nplasma due to excess thyroxin, stopping the thyroxin (option A) will not lead to rapid improvement of\nsymptoms.\nAtropine (option D) and pacemakers (option E) are used for treatment of symptomatic bradycardia, which\nis not the case here.","source_answer_status":"source_revealed","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","anticoag","dose","duration","hypertension","management","treatment"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","record_type":"text_mcq","options_mode":"text","parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","stem_hash":"624071963e775eafd17eb3e503ed7fc6a1a0ece7","duplicate_group_id":"exact-624071963e77","duplicate_sources":[{"record_id":"3dfc90177b1f3c58ad06","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":56,"source_qid":null},{"record_id":"251531e5319a1b2bc9b7","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":168,"source_qid":null},{"record_id":"33c584f7a77e843c4e74","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":37,"source_qid":"246"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
