INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('4fe9de94e741113dac05','Cardiology amedex 2025.pdf','60','Cardiology','Which one of the following signs mandates emergency surgical intervention in acute limb ischemia?','{"A":"A. Pallor.","B":"B. Coldness.","C":"OC. Paralysis.","D":"D. Pain at rest.","E":"E. Pulselessness."}','C','Paralysis is present when a patient with acute limb ischemia is unable to wriggle the toes or fingers. It is
the most reliable sign indicating acute limb ischemia requiring emergency surgical

intervention. Paresthesia of the affected limb is another indicator of acute limb ischemia and can be used
in the absence of paralysis.

(Option A) Pallor is among the signs suggesting acute limb ischemia; however, the color of the limb may
be affected by the ambient light.

(Option B) Coldness of the limb is the least reliable sign as it can be due to decreased body temperature
of the patient to cold weather.

(Option D) Pain (either with exertion or at rest) and pallor can be caused by chronic ischemia as well, and
are not reliable indicators of the need for emergency surgical treatment.

(Option E) Pulselessness can be a sign of acute limb ischemia, but paralysis remains the most critical
indicator.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[60],"source_qid":null,"duplicate_group_id":"exact-a5de25a1bbff","duplicate_sources":[{"record_id":"4fe9de94e741113dac05","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":60,"source_qid":null},{"record_id":"4379df1d9d44aa8fe818","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":109,"source_qid":null},{"record_id":"08e8d0afb707475397d6","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":110,"source_qid":null},{"record_id":"8a4327d2dd0df0e05c2d","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":53,"source_qid":"263"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"4fe9de94e741113dac05","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":60,"supporting_pages":[60],"source_qid":null,"domain_hint":"Cardiology","stem":"Which one of the following signs mandates emergency surgical intervention in acute limb ischemia?","options":{"A":"A. Pallor.","B":"B. Coldness.","C":"OC. Paralysis.","D":"D. Pain at rest.","E":"E. Pulselessness."},"source_answer":"C","source_explanation":"Paralysis is present when a patient with acute limb ischemia is unable to wriggle the toes or fingers. It is\nthe most reliable sign indicating acute limb ischemia requiring emergency surgical\n\nintervention. Paresthesia of the affected limb is another indicator of acute limb ischemia and can be used\nin the absence of paralysis.\n\n(Option A) Pallor is among the signs suggesting acute limb ischemia; however, the color of the limb may\nbe affected by the ambient light.\n\n(Option B) Coldness of the limb is the least reliable sign as it can be due to decreased body temperature\nof the patient to cold weather.\n\n(Option D) Pain (either with exertion or at rest) and pallor can be caused by chronic ischemia as well, and\nare not reliable indicators of the need for emergency surgical treatment.\n\n(Option E) Pulselessness can be a sign of acute limb ischemia, but paralysis remains the most critical\nindicator.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"a5de25a1bbff392003392cb4aa76ef57f01e5f35","duplicate_group_id":"exact-a5de25a1bbff","duplicate_sources":[{"record_id":"4fe9de94e741113dac05","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":60,"source_qid":null},{"record_id":"4379df1d9d44aa8fe818","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":109,"source_qid":null},{"record_id":"08e8d0afb707475397d6","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":110,"source_qid":null},{"record_id":"8a4327d2dd0df0e05c2d","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":53,"source_qid":"263"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
