INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('4fe9de94e741113dac05','src-v294-eaee30a7',NULL,'60','Cardiology','Cardiology','Cardiology','AMC MCQ','Which one of the following signs mandates emergency surgical intervention in acute limb ischemia?',NULL,'C','Paralysis is present when a patient with acute limb ischemia is unable to wriggle the toes or fingers. It is
the most reliable sign indicating acute limb ischemia requiring emergency surgical

intervention. Paresthesia of the affected limb is another indicator of acute limb ischemia and can be used
in the absence of paralysis.

(Option A) Pallor is among the signs suggesting acute limb ischemia; however, the color of the limb may
be affected by the ambient light.

(Option B) Coldness of the limb is the least reliable sign as it can be due to decreased body temperature
of the patient to cold weather.

(Option D) Pain (either with exertion or at rest) and pallor can be caused by chronic ischemia as well, and
are not reliable indicators of the need for emergency surgical treatment.

(Option E) Pulselessness can be a sign of acute limb ischemia, but paralysis remains the most critical
indicator.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[60],"source_qid":null,"duplicate_group_id":"exact-a5de25a1bbff","duplicate_sources":[{"record_id":"4fe9de94e741113dac05","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":60,"source_qid":null},{"record_id":"4379df1d9d44aa8fe818","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":109,"source_qid":null},{"record_id":"08e8d0afb707475397d6","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":110,"source_qid":null},{"record_id":"8a4327d2dd0df0e05c2d","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":53,"source_qid":"263"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','medium') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.pr