INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('447f5995770ffaa64cb7','Cardiology amedex 2025.pdf','61','Cardiology','A 65-year-old man presents to the emergency department with sudden onset right-
sided leg pain and paresthesia. On physical examination, the distal pulses of the
right leg are absent and the limb is cold. ACT angiography is arranged showing
thrombotic occlusion of the right femoral artery. Which one of the following is the next
best step in management?','{"A":"OA. Intravenous infusion of heparin and emergency embolectomy.","B":"B. Intravenous infusion of heparin for 24 hours and review.","C":"C. Complete bed rest with a compression bandage and leg elevation.","D":"D. Start the patient on warfarin.","E":"E. Start the patient on aspirin and clopidogrel."}','A','The clinical and imaging findings are quite consistent with acute limb ischemia.
Paralysis, paresthesia, and compartment syndrome are ominous signs that demand
emergency surgical intervention after heparin has been started. The golden time for
surgical intervention is 4 hours. Signs of ischemia are reversible if prompt action is
taken within this period. Prolonged acute ischemia(>6 hours) leaves irreversible and
permanent deficits. The rest of the management could include catheter-directed
thrombolysis, per-cutaneous thromboaspiration, etc.

Of the option, only option A recommends the use of heparin and is correct.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[61],"source_qid":null,"duplicate_group_id":"exact-450c88eb5f6b","duplicate_sources":[{"record_id":"447f5995770ffaa64cb7","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":61,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"447f5995770ffaa64cb7","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":61,"supporting_pages":[61],"source_qid":null,"domain_hint":"Cardiology","stem":"A 65-year-old man presents to the emergency department with sudden onset right-\nsided leg pain and paresthesia. On physical examination, the distal pulses of the\nright leg are absent and the limb is cold. ACT angiography is arranged showing\nthrombotic occlusion of the right femoral artery. Which one of the following is the next\nbest step in management?","options":{"A":"OA. Intravenous infusion of heparin and emergency embolectomy.","B":"B. Intravenous infusion of heparin for 24 hours and review.","C":"C. Complete bed rest with a compression bandage and leg elevation.","D":"D. Start the patient on warfarin.","E":"E. Start the patient on aspirin and clopidogrel."},"source_answer":"A","source_explanation":"The clinical and imaging findings are quite consistent with acute limb ischemia.\nParalysis, paresthesia, and compartment syndrome are ominous signs that demand\nemergency surgical intervention after heparin has been started. The golden time for\nsurgical intervention is 4 hours. Signs of ischemia are reversible if prompt action is\ntaken within this period. Prolonged acute ischemia(>6 hours) leaves irreversible and\npermanent deficits. The rest of the management could include catheter-directed\nthrombolysis, per-cutaneous thromboaspiration, etc.\n\nOf the option, only option A recommends the use of heparin and is correct.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","thrombol"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"450c88eb5f6b2daf856cd636334f59892397ed63","duplicate_group_id":"exact-450c88eb5f6b","duplicate_sources":[{"record_id":"447f5995770ffaa64cb7","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":61,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
