INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('e8bf94884c98af14a30f','src-v294-eaee30a7',NULL,'64','Cardiology','Cardiology','Cardiology','AMC MCQ','Which one of the following is not associated with increased serum troponin level?',NULL,'E','There is a long list of conditions that can lead to elevated serum troponin levels in the absence of acute coronary syndrome and myocardial infarction. Bradyarrhythmias do not
cause elevated serum troponin levels.

The causes for elevation of serum troponin levels are summarized in the following table:

¢ Aortic dissection.

¢ Sustained tachyarrhythmias

¢ Medical ICU patients

¢ Hypotension

¢ Heat failure

¢ Apical ballooning syndrome
Cardiovascular ¢ Endocarditis and pericarditis

¢ Hypertension

¢ Sarcoidosis, Amyloidosis,

haemochromatosis
¢ Scleroderma and lupus
¢ Left ventricular hypertrophy

¢ Blunt chest trauma
¢ Cardiac surgeries and other
invasive interventions
¢« Chemotherapy with cardiotoxic
Myocardial injury drugs
¢ Hypersensitivity drug reactions
* envenomation

¢ Pulmonary embolism
Respiratory e ARDS

¢ Sepsis / Systemic inflammatory
response syndrome (SIRS)
¢ Viral illness
Infections/immune * Thrombocytopenic thrombotic
purpura

Gastrointestinal * Severe Gl bleeding

¢ Acute stroke (haemorrhagic or
CNS ischaemic)
¢ Head trauma

¢ Diabetes mellitus
Endocrine ¢ hypothyroidism

Musculoskeletal * Rhabdomyolysis

Integumentary * Burns

Neurofibromatosis
Duchenne muscular dystrophy
Kippel-Feil syndrome

Inherited

e Endurance exercise
Other ¢ Environmental: carbon monoxide,
hydrogen sulfide',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[64],"source_qid":null,"duplicate_group_id":"exact-46e806ba9fc3","duplicate_sources":[{"record_id":"e8bf94884c98af14a30f","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":64,"source_qid":null},{"record_id":"9f062d5fa91e1c7ca86f","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (2).pdf","source_page":108,"source_qid":null},{"record_id":"c45333db304c4311089e","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (2).pdf","source_page":109,"source_qid":null},{"record_id":"c57e739ab76758ac25d2","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":75,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded