INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('e49426377ebe05b390ef','Cardiology amedex 2025.pdf','68','Cardiology','Steven is a 65-year-old man, who is a known case of congestive heart failure. He had been stable on enalapril,
metoprolol and digoxin until three weeks ago when his wife passed away from breast cancer. Since then, he
stopped taking his medication. Today, he is brought to the emergency department by his son, with complaints of
shortness of breath, night coughs and ankle edema. On examination, he has a blood pressure of 90/75mmHg,
heart rate of 68 bpm, and respiratory rate of 26 breaths per minute. On auscultation, an S3 gallop is noted, but
there is no crackle. You decide to start him on medication again. Which one of the following would be the best
option to start with?','{"A":"OA. Start him on enalapril.","B":"B. Start him on metoprolol.","C":"C. Start him on digoxin.","D":"D. Start him on enalapril, digoxin and metoprolol at the same time.","E":"E. Start him on enalapril and metoprolol."}','A','The case describes a patient, with congestive cardiac failure, who has been under control with three medications,
but his heart condition has been decompensated due to drug withdrawal.

At this moment, and based on physical findings, the patient has not pulmonary edema (no comments on basal
crackles).

Angiotensin converting enzyme (ACE) inhibitors (e.g. enalapril) improve prognosis in all patients in all grades of
heart failure and should be used as initial therapy in all patients. Angiotensin I| receptor blockers (ARBs) such as
losartan are used when ACE inhibitors cannot be tolerated .

Diuretics are added to ACE inhibitors to help control congestive symptoms and signs.

Beta blockers should only be started when the patient is stable and euvolemic. As this patient has S3 gallop and
ankle edema (signs of hypervolemia), any options suggesting beta blockers (e.g. metoprolol) as initial treatment
would be incorrect.

Digoxin is used in patients with heart failure if:

¢ Heart failure is caused by atrial fibrillation (often in conjuction with beta blockers if the patient is euvolemic)

¢ In patients with heart failure, who have sinus rhythm, but medications such as ACE inhibitors, diuretics have
not adequately controlled their symptoms

¢ In patients with significantly decreased ejection fraction (EF) (<35%)','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[68],"source_qid":null,"duplicate_group_id":"exact-cb04c1bd9adb","duplicate_sources":[{"record_id":"e49426377ebe05b390ef","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":68,"source_qid":null},{"record_id":"22c9ee269d32e5616a23","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":23,"source_qid":"233"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"e49426377ebe05b390ef","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":68,"supporting_pages":[68],"source_qid":null,"domain_hint":"Cardiology","stem":"Steven is a 65-year-old man, who is a known case of congestive heart failure. He had been stable on enalapril,\nmetoprolol and digoxin until three weeks ago when his wife passed away from breast cancer. Since then, he\nstopped taking his medication. Today, he is brought to the emergency department by his son, with complaints of\nshortness of breath, night coughs and ankle edema. On examination, he has a blood pressure of 90/75mmHg,\nheart rate of 68 bpm, and respiratory rate of 26 breaths per minute. On auscultation, an S3 gallop is noted, but\nthere is no crackle. You decide to start him on medication again. Which one of the following would be the best\noption to start with?","options":{"A":"OA. Start him on enalapril.","B":"B. Start him on metoprolol.","C":"C. Start him on digoxin.","D":"D. Start him on enalapril, digoxin and metoprolol at the same time.","E":"E. Start him on enalapril and metoprolol."},"source_answer":"A","source_explanation":"The case describes a patient, with congestive cardiac failure, who has been under control with three medications,\nbut his heart condition has been decompensated due to drug withdrawal.\n\nAt this moment, and based on physical findings, the patient has not pulmonary edema (no comments on basal\ncrackles).\n\nAngiotensin converting enzyme (ACE) inhibitors (e.g. enalapril) improve prognosis in all patients in all grades of\nheart failure and should be used as initial therapy in all patients. Angiotensin I| receptor blockers (ARBs) such as\nlosartan are used when ACE inhibitors cannot be tolerated .\n\nDiuretics are added to ACE inhibitors to help control congestive symptoms and signs.\n\nBeta blockers should only be started when the patient is stable and euvolemic. As this patient has S3 gallop and\nankle edema (signs of hypervolemia), any options suggesting beta blockers (e.g. metoprolol) as initial treatment\nwould be incorrect.\n\nDigoxin is used in patients with heart failure if:\n\n¢ Heart failure is caused by atrial fibrillation (often in conjuction with beta blockers if the patient is euvolemic)\n\n¢ In patients with heart failure, who have sinus rhythm, but medications such as ACE inhibitors, diuretics have\nnot adequately controlled their symptoms\n\n¢ In patients with significantly decreased ejection fraction (EF) (<35%)","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["drug","therapy","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"cb04c1bd9adb7c701725f9cb9d7a72d0c76b7d04","duplicate_group_id":"exact-cb04c1bd9adb","duplicate_sources":[{"record_id":"e49426377ebe05b390ef","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":68,"source_qid":null},{"record_id":"22c9ee269d32e5616a23","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":23,"source_qid":"233"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
