INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('e5126c2349a877bac9b4','Cardiology amedex 2025.pdf','71','Cardiology','A 55-year-old man presents to the emergency department after sudden onset of pain and
paresthesia in his left leg. On examination, the distal pulses of the left lower limb are absent and
the limb is cold and painful. ACT angiogram is performed and establishes the presence of
femoral artery embolism. The patient was started on intravenous heparin and embolectomy was
carried out. Which one of the following is the next best step in management?','{"A":"A. Aspirin and warfarin for 6 months.","B":"B. Lifelong aspirin.","C":"OC. Warfarin for 3-6 months.","D":"D. Low molecular weight heparin for six months and lifelong warfarin afterwards.","E":"E. Heparin for one week."}','C','Every patient with acute limb ischemia must be started on anticoagulation therapy with warfarin
after embolectomy is performed. Heparin cover should not be withheld until the INR is in the
therapeutic range of 2-3.

Long-term warfarin should be considered following embolism from a cardiac source; otherwise 3-
6 months warfarin may suffice.

Aspirin is indicated in patients with atherosclerotic changes of the peripheral arteries and chronic
limb ischemia. It has no role in management of acute limb ischemia.

Combination of aspirin and warfarin is not shown to benefit the patient more than warfarin alone
in terms of preventing further thromboembolic events. Furthermore using these two drugs in
combination increases the risk of bleeding.

Heparin is only used until the INR is in the therapeutic range and withheld afterwards. This goal is
usually achieved in 2-3 days.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[71],"source_qid":null,"duplicate_group_id":"exact-0de333eb7c60","duplicate_sources":[{"record_id":"e5126c2349a877bac9b4","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":71,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"e5126c2349a877bac9b4","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":71,"supporting_pages":[71],"source_qid":null,"domain_hint":"Cardiology","stem":"A 55-year-old man presents to the emergency department after sudden onset of pain and\nparesthesia in his left leg. On examination, the distal pulses of the left lower limb are absent and\nthe limb is cold and painful. ACT angiogram is performed and establishes the presence of\nfemoral artery embolism. The patient was started on intravenous heparin and embolectomy was\ncarried out. Which one of the following is the next best step in management?","options":{"A":"A. Aspirin and warfarin for 6 months.","B":"B. Lifelong aspirin.","C":"OC. Warfarin for 3-6 months.","D":"D. Low molecular weight heparin for six months and lifelong warfarin afterwards.","E":"E. Heparin for one week."},"source_answer":"C","source_explanation":"Every patient with acute limb ischemia must be started on anticoagulation therapy with warfarin\nafter embolectomy is performed. Heparin cover should not be withheld until the INR is in the\ntherapeutic range of 2-3.\n\nLong-term warfarin should be considered following embolism from a cardiac source; otherwise 3-\n6 months warfarin may suffice.\n\nAspirin is indicated in patients with atherosclerotic changes of the peripheral arteries and chronic\nlimb ischemia. It has no role in management of acute limb ischemia.\n\nCombination of aspirin and warfarin is not shown to benefit the patient more than warfarin alone\nin terms of preventing further thromboembolic events. Furthermore using these two drugs in\ncombination increases the risk of bleeding.\n\nHeparin is only used until the INR is in the therapeutic range and withheld afterwards. This goal is\nusually achieved in 2-3 days.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","anticoag","drug","management","therapy","warfarin"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"0de333eb7c60ea340899d4d0f34a1acc2dd7a07c","duplicate_group_id":"exact-0de333eb7c60","duplicate_sources":[{"record_id":"e5126c2349a877bac9b4","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":71,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
