INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f79dde20494bc602d4ae','Cardiology amedex 2025.pdf','72','Cardiology','Which one of the following is the most appropriate course of action for pulseless
electrical activity?',NULL,'C','Pulseless electrical activity (PEA) is managed by starting CPR (30:2) immediately,
securing an airway and providing intravenous access. If not responsive, IV adrenaline
should be given. Looking for a correctable cause of PEA and correcting that is always
an important part of management.

Defibrillation has no role in management of PEA as the organized electrical activity of
the heart is preserved.

There is no recommendation to support the use of atropine in PEA or asystole.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[72],"source_qid":null,"duplicate_group_id":"exact-48642295e67a","duplicate_sources":[{"record_id":"f79dde20494bc602d4ae","record_type":"visual_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":72,"source_qid":null},{"record_id":"87d86bd866cf793f91f0","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":82,"source_qid":"288"}],"parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","parser_mode":"v282_visual_page_asset","text_method":"source_page_image+best_available_text","visual_asset":"visual_assets/Cardiology_amedex_2025__a83b80e8c658/page_00072.jpg","asset_preview_url":"https://drive.google.com/file/d/1xakTb52kB8Z-O3np5hXCao6bu4KJCRMe/preview"}','visual_assets/Cardiology_amedex_2025__a83b80e8c658/page_00072.jpg','https://drive.google.com/thumbnail?id=1xakTb52kB8Z-O3np5hXCao6bu4KJCRMe&sz=w1600','source_page_image',NULL,'needs_verification','[]','low','{"record_id":"f79dde20494bc602d4ae","record_type":"visual_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":72,"supporting_pages":[72],"source_qid":null,"domain_hint":"Cardiology","stem":"Which one of the following is the most appropriate course of action for pulseless\nelectrical activity?","options":null,"options_mode":"source_page_image","visual_asset":"visual_assets/Cardiology_amedex_2025__a83b80e8c658/page_00072.jpg","source_answer":"C","source_explanation":"Pulseless electrical activity (PEA) is managed by starting CPR (30:2) immediately,\nsecuring an airway and providing intravenous access. If not responsive,