INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('1cda6b75cd0ffd84f57c','Cardiology amedex 2025.pdf','76','Cardiology','A 60-year-old man presents to the Emergency Department with complaint of
vague abdominal pain. On examination, there is mild abdominal tenderness in
the epigastric area with a vaguely palpated abdominal mass. On auscultation, a
bruit is heard over the mass. Which one of the following is the next step in
management?','{"A":"A. Aortogram.","B":"OB. Emergency bedside ultrasonography.","C":"C.Non-contrast abdominal CT scan.","D":"D. Erect and supine abdominal X-rays.","E":"E. Immediate transfer of the patient to the operating room."}','B','The findings are consistent with provisional diagnosis of abdominal aortic
aneurysm (AAA). Physical examination is only moderately sensitive for
diagnosis; therefore, a bedside ultrasonography for confirming the diagnosis of
AAA is the next best step in management. Ultrasonography is the preferred
diagnostic method for AAAs with high accuracy.

Spiral CT scan gives visualization of the aneurysm and surrounding structures. It
is only indicated prior to elective surgical repair. It is never used to make a
diagnosis of AAA. CT angiography with intravenous contrast can be used for
assessment, but non-contrast CT and abdominal X-rays are of no use to
diagnose AAA.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[76],"source_qid":null,"duplicate_group_id":"exact-3c09ad9d5fb1","duplicate_sources":[{"record_id":"1cda6b75cd0ffd84f57c","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":76,"source_qid":null},{"record_id":"84a1732e7486cfe073a3","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":7,"source_qid":null},{"record_id":"7261328731e12471ecde","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":42,"source_qid":"252"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"1cda6b75cd0ffd84f57c","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":76,"supporting_pages":[76],"source_qid":null,"domain_hint":"Cardiology","stem":"A 60-year-old man presents to the Emergency Department with complaint of\nvague abdominal pain. On examination, there is mild abdominal tenderness in\nthe epigastric area with a vaguely palpated abdominal mass. On auscultation, a\nbruit is heard over the mass. Which one of the following is the next step in\nmanagement?","options":{"A":"A. Aortogram.","B":"OB. Emergency bedside ultrasonography.","C":"C.Non-contrast abdominal CT scan.","D":"D. Erect and supine abdominal X-rays.","E":"E. Immediate transfer of the patient to the operating room."},"source_answer":"B","source_explanation":"The findings are consistent with provisional diagnosis of abdominal aortic\naneurysm (AAA). Physical examination is only moderately sensitive for\ndiagnosis; therefore, a bedside ultrasonography for confirming the diagnosis of\nAAA is the next best step in management. Ultrasonography is the preferred\ndiagnostic method for AAAs with high accuracy.\n\nSpiral CT scan gives visualization of the aneurysm and surrounding structures. It\nis only indicated prior to elective surgical repair. It is never used to make a\ndiagnosis of AAA. CT angiography with intravenous contrast can be used for\nassessment, but non-contrast CT and abdominal X-rays are of no use to\ndiagnose AAA.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"3c09ad9d5fb11c3c74a921a6090bb942c121f4b2","duplicate_group_id":"exact-3c09ad9d5fb1","duplicate_sources":[{"record_id":"1cda6b75cd0ffd84f57c","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":76,"source_qid":null},{"record_id":"84a1732e7486cfe073a3","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":7,"source_qid":null},{"record_id":"7261328731e12471ecde","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":42,"source_qid":"252"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=e